#!/bin/sh
# Tier 1 wrapper for Claude Code, profile ${PROFILE_NAME}.
# Generated by devkit; edits are lost on `devkit profile sync`.
# The public name is claude-<profile>; this script execs the stock CLI by
# absolute path so a profile bin/ named `claude` cannot loop.
set -eu
CLAUDE_CONFIG_DIR="${PROFILE_CONFIG_DIR}"
export CLAUDE_CONFIG_DIR
exec "${PROFILE_CLAUDE_CLI}" "$@"
